# A.3 characterisation (golden) tests: current output of CalcUnmarkedClass,
# CalcMarkedClass and Classes on the canonical grid, compared to golden/*.rds
# (generated by make_golden.R on unmodified code at f70c00a).

golden_files <- sort(list.files("golden", pattern = "\\.rds$", full.names = TRUE))

test_that("all six golden files exist", {
  expect_length(golden_files, length(IMAX_SET) * length(INTERFERE_SETS))
})

for (f in golden_files) {
  local({
    f <- f
    test_that(paste("golden:", basename(f)), {
      gold <- readRDS(f)
      g <- make_grid()
      expect_equal(gold$grid, g, tolerance = 1e-10)
      expect_equal(solve_grid(g, gold$imax, gold$which.interfere, "unmarked"),
                   gold$unmarked, tolerance = 1e-10)
      expect_equal(solve_grid(g, gold$imax, gold$which.interfere, "marked"),
                   gold$marked, tolerance = 1e-10)
      expect_equal(solve_grid(g, gold$imax, gold$which.interfere, "classes"),
                   gold$classes, tolerance = 1e-10)
      # shape contract: one column per grid row, imax+1 rows (class 0 included)
      expect_equal(dim(gold$unmarked), c(gold$imax + 1, nrow(g)))
    })
  })
}

test_that("return shapes: unmarked is an (imax+1) x 1 matrix; marked is a plain vector; class 0 included", {
  p <- par_vec(make_grid()[100, ])
  u <- CalcUnmarkedClass(p, 39); m <- CalcMarkedClass(p, 39); cl <- Classes(p, 39)
  expect_equal(dim(u), c(40L, 1L))          # Solve.tridiag returns a one-column matrix
  expect_null(dim(m)); expect_length(m, 40)  # vapply result
  expect_equal(dim(cl), c(40L, 1L))          # matrix + vector -> matrix
  expect_equal(as.numeric(cl), as.numeric(u) + m, tolerance = 1e-12)
  # parameters may be passed unnamed (par.names fallback)
  expect_equal(as.numeric(CalcUnmarkedClass(unname(p), 39)), as.numeric(u))
})
